"""Git publishing: auto-commit and auto-push to the archive branch.

Strictly scoped: all git runs through ``git -C <archive worktree>`` and stage
only the archive subdir. Structurally incapable of opening a PR or touching
another branch. On push failure the local commit is kept for retry; never
force-pushes.
"""

from __future__ import annotations

import subprocess
from dataclasses import dataclass
from pathlib import Path


class PublishError(RuntimeError):
    pass


@dataclass
class PublishResult:
    status: str  # "noop" | "pushed" | "push_failed"
    commit: str | None = None
    detail: str = ""


class Publisher:
    def __init__(self, worktree: Path, subdir: str, branch: str, remote: str = "origin"):
        self.worktree = Path(worktree)
        self.subdir = subdir
        self.branch = branch
        self.remote = remote

    def _git(self, *args: str, check: bool = True) -> subprocess.CompletedProcess:
        return subprocess.run(
            ["git", "-C", str(self.worktree), *args],
            capture_output=True, text=True, check=check,
        )

    def current_branch(self) -> str:
        return self._git("rev-parse", "--abbrev-ref", "HEAD").stdout.strip()

    def _has_upstream(self) -> bool:
        return self._git(
            "rev-parse", "--abbrev-ref", "--symbolic-full-name", "@{u}", check=False
        ).returncode == 0

    def _staged_empty(self) -> bool:
        # diff --cached --quiet exits 0 when there is nothing staged.
        return self._git("diff", "--cached", "--quiet", check=False).returncode == 0

    def publish(self, commit_message: str) -> PublishResult:
        if not self.worktree.exists():
            raise PublishError(f"Archive worktree missing: {self.worktree}")
        actual = self.current_branch()
        if actual != self.branch:
            raise PublishError(
                f"Refusing to publish: on branch '{actual}', expected '{self.branch}'."
            )

        self._git("add", "--", self.subdir)
        if self._staged_empty():
            return PublishResult(status="noop", detail="no changes to commit")

        self._git("commit", "-m", commit_message)
        commit = self._git("rev-parse", "HEAD").stdout.strip()

        # Converge with remote before pushing (handles restarts / other machines).
        if self._has_upstream():
            rebase = self._git("pull", "--rebase", self.remote, self.branch, check=False)
            if rebase.returncode != 0:
                self._git("rebase", "--abort", check=False)
                raise PublishError(
                    f"Rebase conflict while pulling {self.remote}/{self.branch}; "
                    f"local commit {commit[:8]} kept. Resolve manually."
                )

        push = self._git("push", self.remote, self.branch, check=False)
        if push.returncode != 0:
            return PublishResult(
                status="push_failed", commit=commit,
                detail=(push.stderr or push.stdout).strip(),
            )
        return PublishResult(status="pushed", commit=commit)

"""Event-driven watcher: real inotify via ``inotifywait``, plus a testable
debounce core and a single-instance lock.

The debounce logic is separated from the event source and takes an injected
clock so it can be unit-tested without real filesystem timing.
"""

from __future__ import annotations

import errno
import os
import select
import signal
import subprocess
import time
from pathlib import Path

INOTIFY_EVENTS = "create,close_write,modify,moved_to"


class Debouncer:
    """Collapse a burst of events into one dispatch after a quiet window."""

    def __init__(self, quiet_seconds: float):
        self.quiet_seconds = quiet_seconds
        self._pending: set[str] = set()
        self._deadline: float | None = None

    def add(self, key: str, now: float) -> None:
        self._pending.add(key)
        self._deadline = now + self.quiet_seconds

    @property
    def pending(self) -> bool:
        return bool(self._pending)

    def seconds_until_due(self, now: float) -> float | None:
        if self._deadline is None:
            return None
        return max(0.0, self._deadline - now)

    def due(self, now: float) -> bool:
        return bool(self._pending) and self._deadline is not None and now >= self._deadline

    def pop(self) -> set[str]:
        keys, self._pending = self._pending, set()
        self._deadline = None
        return keys


# --- single-instance lock ---------------------------------------------

class LockError(RuntimeError):
    pass


def acquire_lock(lock_file: Path) -> Path:
    lock_file.parent.mkdir(parents=True, exist_ok=True)
    if lock_file.exists():
        if _lock_alive(lock_file):
            raise LockError(f"Watcher already running (lock: {lock_file}).")
        lock_file.unlink(missing_ok=True)  # stale
    fd = os.open(lock_file, os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o644)
    with os.fdopen(fd, "w") as fh:
        fh.write(f"{os.getpid()}\n{time.time()}\nwatch\n")
    return lock_file


def release_lock(lock_file: Path) -> None:
    lock_file.unlink(missing_ok=True)


def _lock_alive(lock_file: Path) -> bool:
    try:
        pid = int(lock_file.read_text(encoding="utf-8").splitlines()[0])
    except (ValueError, IndexError, OSError):
        return False
    try:
        os.kill(pid, 0)
        return True
    except OSError as exc:
        return exc.errno == errno.EPERM  # exists but not ours


# --- inotify loop ------------------------------------------------------

def watch(config, on_burst) -> None:
    """Block, dispatching ``on_burst()`` once per debounced burst.

    ``on_burst`` is called with the set of changed session paths. Runs an
    initial dispatch (startup catch-up) before entering the event loop.
    """
    source = config.source_dir()
    lock = acquire_lock(config.lock_file)
    proc = None
    try:
        on_burst(set())  # startup catch-up
        # stdbuf -oL forces line-buffered output: inotifywait block-buffers its
        # stdout when piped, which would otherwise delay/hide MODIFY events on
        # the active session file (Claude appends to it while holding it open).
        proc = subprocess.Popen(
            ["stdbuf", "-oL", "inotifywait", "-m", "-q",
             "-e", INOTIFY_EVENTS, "--format", "%w%f", str(source)],
            stdout=subprocess.PIPE, text=True,
        )
        deb = Debouncer(config.debounce_seconds)
        while True:
            timeout = deb.seconds_until_due(time.monotonic())
            ready, _, _ = select.select([proc.stdout], [], [], timeout)
            if ready:
                line = proc.stdout.readline()
                if not line:
                    break  # inotifywait exited
                path = line.strip()
                if path.endswith(".jsonl"):
                    deb.add(path, time.monotonic())
            if deb.due(time.monotonic()):
                deb.pop()
                on_burst(set())  # full regeneration; burst content is advisory
    finally:
        if proc and proc.poll() is None:
            proc.send_signal(signal.SIGTERM)
        release_lock(lock)

"""Runtime configuration resolved from environment variables with defaults.

All paths and knobs live here so the rest of the package stays testable: tests
construct a Config pointing at temp directories instead of the real workspace.
"""

from __future__ import annotations

import os
import re
from dataclasses import dataclass
from pathlib import Path

SOURCE_NAME = "claude-code"


def encode_cwd(path: str) -> str:
    """Encode a working-directory path the way Claude Code names project dirs.

    Every non-alphanumeric character becomes ``-`` so ``/workspaces/fhir-agent``
    -> ``-workspaces-fhir-agent`` and ``/workspaces/.ai-chat-history`` ->
    ``-workspaces--ai-chat-history``.
    """
    return re.sub(r"[^A-Za-z0-9]", "-", path)


@dataclass
class Config:
    # Where Claude Code stores sessions.
    projects_base: Path
    source_worktree: str
    conversation_dir_override: Path | None
    # Where the archive is written / committed.
    archive_worktree: Path
    archive_subdir: str
    branch: str
    remote: str
    # Behaviour.
    debounce_seconds: float

    @classmethod
    def from_env(cls, env: dict[str, str] | None = None) -> "Config":
        env = dict(os.environ if env is None else env)
        home = Path(env.get("HOME", str(Path.home())))
        override = env.get("CLAUDE_CONVERSATION_DIR")
        return cls(
            projects_base=Path(env.get("CLAUDE_PROJECTS_BASE", home / ".claude" / "projects")),
            source_worktree=env.get("ARCHIVE_SOURCE_WORKTREE", "/workspaces/fhir-agent"),
            conversation_dir_override=Path(override) if override else None,
            archive_worktree=Path(env.get("ARCHIVE_WORKTREE", "/workspaces/.ai-chat-history")),
            archive_subdir=env.get("ARCHIVE_SUBDIR", "ai-chat-documentation"),
            branch=env.get("ARCHIVE_BRANCH", "ai-chat-history"),
            remote=env.get("ARCHIVE_REMOTE", "origin"),
            debounce_seconds=float(env.get("AI_ARCHIVE_DEBOUNCE_SECONDS", "15")),
        )

    # --- derived paths -------------------------------------------------
    @property
    def archive_root(self) -> Path:
        return self.archive_worktree / self.archive_subdir

    @property
    def raw_dir(self) -> Path:
        return self.archive_root / "raw" / SOURCE_NAME

    @property
    def markdown_dir(self) -> Path:
        return self.archive_root / "markdown" / SOURCE_NAME

    @property
    def index_path(self) -> Path:
        return self.archive_root / "INDEX.md"

    @property
    def manifest_path(self) -> Path:
        return self.archive_root / "manifests" / f"{SOURCE_NAME}.json"

    @property
    def config_dir(self) -> Path:
        return self.archive_root / "config"

    @property
    def patterns_file(self) -> Path:
        return self.config_dir / "redaction-patterns.txt"

    @property
    def exclusions_file(self) -> Path:
        return self.config_dir / "exclusions.txt"

    @property
    def lock_file(self) -> Path:
        return self.archive_root / "logs" / "watcher.lock"

    def source_dir(self) -> Path:
        """The Claude Code project directory whose sessions we archive."""
        if self.conversation_dir_override is not None:
            return self.conversation_dir_override
        return self.projects_base / encode_cwd(self.source_worktree)

    def excluded_source_dir(self) -> Path:
        """The archive worktree's own project dir — never archive ourselves."""
        return self.projects_base / encode_cwd(str(self.archive_worktree))

    def load_exclusions(self) -> set[str]:
        return _read_lines(self.exclusions_file)


def _read_lines(path: Path) -> set[str]:
    if not path.exists():
        return set()
    out: set[str] = set()
    for line in path.read_text(encoding="utf-8").splitlines():
        line = line.strip()
        if line and not line.startswith("#"):
            out.add(line)
    return out

